#include <stddef.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>

int32_t native_add(int32_t a, int32_t b) {
    return a + b;
}

pid_t native_getpid(void) {
    return getpid();
}

size_t native_strlen(const char *s) {
    return strlen(s);
}

use libc::{c_char, c_int, pid_t};
use std::ffi::CStr;

unsafe extern "C" {
    fn native_add(a: c_int, b: c_int) -> c_int;
    fn native_getpid() -> pid_t;
    fn native_strlen(s: *const c_char) -> usize;
}

fn main() {
    let sum = unsafe { native_add(20, 22) };
    println!("native_add(20, 22) = {sum}");

    let pid = unsafe { native_getpid() };
    println!("native_getpid() = {pid} (std::process::id() = {})", std::process::id());

    let name = c"systems_tool";
    let len = unsafe { native_strlen(name.as_ptr()) };
    println!("native_strlen({:?}) = {len}", name);

    let os = unsafe {
        let mut buf = libc::utsname {
            sysname: [0; 65],
            nodename: [0; 65],
            release: [0; 65],
            version: [0; 65],
            machine: [0; 65],
            domainname: [0; 65],
        };
        if libc::uname(&mut buf) == 0 {
            CStr::from_ptr(buf.sysname.as_ptr()).to_string_lossy().into_owned()
        } else {
            "unknown".to_string()
        }
    };
    println!("libc::uname sysname = {os}");
}

